def context_compression_ratio(total_tools: int = 1_000_000, top_k: int = 15, tokens_per_tool: int = 165) -> dict:
    raw_tokens = total_tools * tokens_per_tool
    pruned_tokens = top_k * tokens_per_tool
    ratio = 1.0 - (pruned_tokens / raw_tokens)
    return {"raw_tokens": raw_tokens, "pruned_tokens": pruned_tokens, "compression_pct": round(ratio * 100, 4)}

def prune_tools_rrf(dense_ranks: dict[str, int], bm25_ranks: dict[str, int], allowed_ids: set[str], k: int = 60, top_n: int = 15) -> list[str]:
    scores = {}
    for tid in allowed_ids:
        if tid in dense_ranks or tid in bm25_ranks:
            scores[tid] = (1.0 / (k + dense_ranks.get(tid, 1000))) + (1.0 / (k + bm25_ranks.get(tid, 1000)))
    return [tid for tid, _ in sorted(scores.items(), key=lambda x: -x[1])[:top_n]]

def maglev_select_backend(session_id: str, lookup_table: list[str]) -> str:
    import hashlib
    if not lookup_table:
        raise ValueError("No healthy multiplexer backends available")
    h = int.from_bytes(hashlib.blake2b(session_id.encode(), digest_size=8).digest(), "little")
    return lookup_table[h % len(lookup_table)]

def compute_effective_scope(user_scopes: set[str], agent_scopes: set[str], tool_required: set[str]) -> set[str]:
    effective = user_scopes & agent_scopes
    if not tool_required.issubset(effective):
        missing = tool_required - effective
        raise PermissionError(f"Cedar ABAC deny: missing scopes {sorted(missing)}")
    return tool_required

def sanitize_tool_output(payload_bytes: bytes, max_bytes: int = 65536, injection_score: float = 0.0) -> str:
    if len(payload_bytes) > max_bytes:
        payload_bytes = payload_bytes[:max_bytes]
    if injection_score > 0.85:
        raise ValueError("Blocked indirect prompt injection in MCP tool output")
    return f"<mcp_tool_output>{payload_bytes.decode('utf-8', errors='replace')}</mcp_tool_output>"

def emit_otel_audit_span(kafka_producer, trace_id: str, tenant_id: str, tool_id: str, status: str) -> None:
    span = {"trace_id": trace_id, "tenant_id": tenant_id, "tool_id": tool_id, "status": status}
    try:
        kafka_producer.produce_async("mcp.otel.audit.v1", key=tenant_id, value=span)
    except BufferError:
        # Non-blocking drop-oldest / spill-to-disk metric increment; never block hot path
        pass
